  { id: 81, name: "Gale Amulet", type: "Сборный артефакт", recipe: "7 + 64 + 1 + 32", desc: "Активный эффект: Даёт союзникам +17,5% к скорости заклинаний и +45 к скорости передвижения на 6 сек. Пассивный эффект: Увеличивает скорость передвижения союзников на 20 в радиусе 1200", stats: { cooldown: 45, str: 7, int: 7 } },
  { id: 82, name: "Vital Shield", type: "Сборный артефакт", recipe: "74 + 21", desc: "Активный эффект: Восстанавливает 27,5% здоровья союзникам в радиусе 1200. Пассивный эффект: Увеличивает восстановление здоровья союзников на 2,5% в радиусе 1200", stats: { cooldown: 120, armor: 4 } },
  { id: 83, name: "Bloodfang Talisman", type: "Сборный артефакт", recipe: "73 + 75 + 19 + 36", desc: "Пассивный эффект: Увеличивает вампиризм союзников на 20%, их мастерство на 1,8%, броню на 2%, восстановление маны на 10. Радиус: 1200", stats: { armor: 2, mpRegen: "0,75", physVamp: 20 } },
  { id: 84, name: "Essence Conduit", type: "Сборный артефакт", recipe: "57 + 10", desc: "Активный эффект: Восстанавливает союзникам 2% здоровья, маны и энергии за каждый заряд. Максимум 60 зарядов, за раз можно использовать до 20. Заряды получаются каждые 2 сек. и когда враг использует способность в радиусе 1200. Пассивный эффект: Лечащие способности владельца восстанавливают на 30% больше здоровья", stats: { cooldown: 16, str: 9, agi: 9, int: 9 } },
  { id: 85, name: "Warding Stone", type: "Сборный артефакт", recipe: "35 + 74 + 49", desc: "Активный эффект: Даёт барьер союзникам в радиусе 1200, поглощающий 20% магического урона. Длительность: 8 сек. Пассивный эффект: Увеличивает восстановление здоровья союзников на 2,5% и сопротивление магии на 10% в радиусе 1200", stats: { cooldown: 45, hpRegen: 14, magicResist: 20 } },
  { id: 86, name: "Manaflow Crest", type: "Сборный артефакт", recipe: "43 + 44 + 46", desc: "", stats: { manaPool: 40, stamina: 40 } },
  { id: 87, name: "Spiritwind Crest", type: "Сборный артефакт", recipe: "78 + 81 + 1", desc: "Активный эффект: Увеличивает скорость заклинаний на 20% и скорость передвижения на 65 на 10 сек. В первые 5 сек. союзников нельзя замедлить. Пассивный эффект: Увеличивает скорость передвижения союзников на 20 в радиусе 1200", stats: { cooldown: 45, str: 8, int: 8, hpRegen: 14, moveSpeed: 65 } },
  { id: 88, name: "Arcane Lifebloom", type: "Сборный артефакт", recipe: "79 + 82 + 73", desc: "Восстанавливает 60% здоровья и 60% маны союзникам в радиусе 1200, снимает с владельца негативные эффекты. Если мана полная, восстанавливает энергию", stats: { cooldown: 60, armor: 4, mpRegen: "1,5", moveSpeed: 50, manaPool: 25 } },
  { id: 89, name: "Venomshroud Amulet", type: "Сборный артефакт", recipe: "83 + 9 + 1 + 1", desc: "Следующая атака отравит цель на 4 сек., замедлит на 25%, наносит урон, равный 90% магического урона в секунду", stats: { cooldown: 9, int: 12, armor: 6, speed: 20, mpRegen: "1,5" } },
  { id: 90, name: "Poisonfang Orb", type: "Сборный артефакт", recipe: "89 + 54", desc: "Следующая атака отравит цель на 4 сек., замедлит на 25%, наносит урон, равный 175% магического урона в секунду", stats: { cooldown: 6, int: 40, armor: 6, speed: 40, manaPool: 50 } },
  { id: 91, name: "Arcane Burst Amulet", type: "Сборный артефакт", recipe: "23 + 9", desc: "Выпускает взрыв радиусом 1200, который увеличивает урон от заклинаний по врагам на 10%. Длительность: 16 сек", stats: { cooldown: 20, str: 4, agi: 4, int: 4, armor: 4, hpRegen: 4 } },
  { id: 92, name: "Shadowveil Mantle", type: "Сборный артефакт", recipe: "37 + 35", desc: "После задержки в 0,5 сек. даёт владельцу или выбранному союзнику невидимость, +40 к скорости передвижения и барьер, поглощающий до 30% магического урона. Действует 5 сек.", stats: { cooldown: 12, magicResist: 25 } },
  { id: 93, name: "Psychic Push Amulet", type: "Сборный артефакт", recipe: "12 + 44 + 1", desc: "Толкает выбранное существо в направлении его взгляда на расстояние 600. Длительность толчка: 0,5 сек. Дальность применения: 550.", stats: { cooldown: 19, str: 15, stamina: 30 } },
  { id: 94, name: "Seer's Pendant", type: "Сборный артефакт", recipe: "43 + 42", desc: "Увеличивает дальность применения способностей и предметов на 225", stats: { mpRegen: "2,5", manaPool: 30 } },
  { id: 95, name: "Levitation Talisman", type: "Сборный артефакт", recipe: "12 + 42 + 32", desc: "Поднимает выбранную цель в воздух, делая её неуязвимой на 2,5 сек. Можно использовать на себя или противника. Если применить на врага, то после приземления он оглушается на 2,5 сек и получит 75% магического урона. Дальность применения: 550.", stats: { cooldown: 23, int: 10 } },
  { id: 96, name: "Aegis of Speed", type: "Сборный артефакт", recipe: "80 + 32 + 9", desc: "Даёт барьер всем союзникам в радиусе 1200, поглощающий 40% физического урона, увеличивает скорость заклинаний на 30% и скорость передвижения на 15. Длительность: 10 сек.", stats: { cooldown: 45, str: 4, agi: 4, int: 4, armor: 4, moveSpeed: 25, manaPool: 30, stamina: 30 } },
  { id: 97, name: "Vampiric Sigil", type: "Сборный артефакт", recipe: "55 + 34", desc: "Выпускает мощный всплеск энергии, наносящий 600% магического урона", stats: { cooldown: 27, str: 15, agi: 15, int: 15, magicVamp: 15 } },
  { id: 98, name: "Silence Pendant", type: "Сборный артефакт", recipe: "67 + 45", desc: "Создаёт область радиусом 200, в которой противники не могут использовать способности 5 сек. По окончании наносит им магический урон в размере 30% от полученного за время действия эффекта предмета", stats: { cooldown: 40, int: 12, speed: 20, mastery: 1, hpRegen: 6, mpRegen: "3,5" } },
  { id: 99, name: "Essence Matrix", type: "Сборный артефакт", recipe: "86 + 39", desc: "Уменьшает время перезарядки всех способностей и предметов на 25%", stats: { mpRegen: 6, manaPool: 60, stamina: 60 } },
  { id: 100, name: "Chrono Sphere", type: "Сборный артефакт", recipe: "45 + 45 + 39 + 41", desc: "Сбрасывает время перезарядки всех ваших предметов и способностей, кроме этого предмета", stats: { cooldown: 90, mastery: 2, hpRegen: 18, mpRegen: 12 } },
  { id: 101, name: "Hexed Amulet", type: "Сборный артефакт", recipe: "54 + 39", desc: "Превращает цель в безобидное существо на 5 сек. Жертва не может атаковать, применять способности или использовать предметы, а её базовая скорость снижается на 90%, при этом получаемый урон по этой цели увеличивается на 25%. Уничтожает иллюзии. Дальность применения: 800", stats: { cooldown: 20, int: 30, mpRegen: "8,5" } },
  { id: 102, name: "Chain Lightning Charm", type: "Сборный артефакт", recipe: "27 + 22 + 20", desc: "Каждая атака с 30% шансом создаёт цепную молнию, которая 4 раза перескакивает между врагами в радиусе 650, нанося им 20% магического урона", stats: { speed: "12,5", mastery: "2,5" } },
  { id: 103, name: "Paralysis Gem", type: "Сборный артефакт", recipe: "12 + 44 + 9", desc: "Накладывает на врага оцепенение на 2 сек.Дальность применения: 1100", stats: { cooldown: 18, int: 15, stamina: 30 } },
  { id: 104, name: "Thunderstorm Amulet", type: "Сборный артефакт", recipe: "102 + 103", desc: "Пассивный эффект: Каждая атака с 40% шансом создаёт создаёт цепную молнию, которая 7 раз перескакивает между врагами в радиусе 650, нанося им 40% магического урона. Активный эффект: Накладывает оцепенение на всех врагов в радиусе 400 и наносит им урон, равный 40% интеллекта владельца. Длительность: 2 сек. Дальность применения: 1100", stats: { cooldown: 13, str: 14, agi: 14, int: 14, speed: 15, mastery: 3, manaPool: 30, stamina: 30 } },
  { id: 105, name: "Levitation Aura", type: "Сборный артефакт", recipe: "54 + 95", desc: "Поднимает цель в воздух, делая её неуязвимой на 2,5 сек. Враги оглушаются при падении на 2,5 сек и получют 125% магического урона, союзники могут двигаться вместе с ураганом. Дальность применения: 550", stats: { cooldown: 16, int: 35, mpRegen: 6, moveSpeed: 50 } },
  { id: 106, name: "Precision Blade", type: "Сборный артефакт", recipe: "19 + 26", desc: "Увеличивает шанс и урон критического удара на 30%", stats: { mastery: "3,2", crit: 30, critDmg: 30 } },
  { id: 107, name: "Protective Emblem", type: "Сборный артефакт", recipe: "41 + 44", desc: "С вероятностью 60% блокирует 20% урона от атак противника", stats: { hpRegen: 7, stamina: 25 } },
  { id: 108, name: "Thorns of Vengeance", type: "Сборный артефакт", recipe: "25 + 21", desc: "Пассивный эффект: Возвращает 20% урона от каждой атаки и заклинания атакующим. Активный эффект: Увеличивает возврат урона от всех источников на 85% на 5,5 сек", stats: { cooldown: 15, armor: 7, mastery: "1,8" } },
  { id: 109, name: "Life Shield Gem", type: "Сборный артефакт", recipe: "43 + 44", desc: "Если здоровье владельца падает ниже 70%, получает магический щит, который снимает большинство отрицательных эффектов и увеличивает сопротивление урону на 75% на 2,5 сек.", stats: { cooldown: 90, manaPool: 25, stamina: 50 } },
  { id: 110, name: "Strength Emblem", type: "Сборный артефакт", recipe: "107 + 52", desc: "Увеличивает силу всех союзников на 10% в радиусе 1200. Союзники в радиусе 1200 с 60% шансом блокируют 30% урона от атак противника", stats: { str: 15, armor: 8, hpRegen: 12, stamina: 25 } },
  { id: 111, name: "Mana Resilience", type: "Сборный артефакт", recipe: "13 + 35 + 44", desc: "Восстанавливает 3 единицы маны каждый раз когда вы получаете урон", stats: { str: 14, magicResist: 25, stamina: 25 } },
  { id: 112, name: "Reflective Aura", type: "Сборный артефакт", recipe: "64 + 32", desc: "Создаёт вокруг вас щит, отражающий направленные заклинания обратно во врага. Длительность: 6 сек.", stats: { cooldown: 15, armor: 15, hpRegen: "6,5", mpRegen: 4, manaPool: 25 } },
  { id: 113, name: "Purification Gem", type: "Сборный артефакт", recipe: "13 + 27", desc: "Даёт невосприимчивость к магии и отрицательным эффектам. Защищает от чистого и отражённого урона. Длительность: 4 сек.", stats: { cooldown: 90, str: 10, mastery: "2,4" } },
  { id: 114, name: "Bloodstone Pendant", type: "Сборный артефакт", recipe: "86 + 34 + 42", desc: "Увеличивает вампиризм и расход маны для заклинаний в 3 раза, ваша мана восполняется в 6 раз эфективней. Длительность: 6 сек", stats: { cooldown: 35, hpRegen: 3, manaPool: 100, stamina: 100, magicVamp: 30 } },
  { id: 115, name: "Divine Ward", type: "Сборный артефакт", recipe: "55 + 64 + 16", desc: "Блокирует направленную в вас способность", stats: { cooldown: 14, str: 16, agi: 16, int: 16, hpRegen: 10, mpRegen: "4,25", stamina: 25 } },
  { id: 116, name: "Arcane Shield", type: "Сборный артефакт", recipe: "48 + 50 + 73", desc: "Увеличивает все сопротивления союзников на 5% и их скорость заклинаний на 25%, снижает все сопротивления врагов поблизости на 5%. Радиус: 1200", stats: { armor: 15 } },
  { id: 117, name: "Mageflare", type: "Сборный артефакт", recipe: "91 + 48", desc: "Выпускает взрыв радиусом 1200, наносящий 110% магического урона, волна увеличивает урон от заклинаний по врагам на 15% и снижает их скорость произнесения заклинаний на 40%. Длительность: 16 сек", stats: { cooldown: 20, str: 5, agi: 5, int: 5, armor: 20, hpRegen: 5 } },
  { id: 118, name: "Titan's Embrace", type: "Сборный артефакт", recipe: "52 + 52 + 4", desc: "", stats: { str: 60, hpRegen: 170 } },
  { id: 119, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "7 + 11", desc: "150+ к дальности атаки", stats: { str: 12, agi: 15 } },
  { id: 120, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "93 + 119", desc: "Толкает выбранное существо в направлении его взгляда на расстояние 600. Длительность толчка: 0,2 сек. Дальность применения: 550. 250+ к дальности атаки", stats: { cooldown: 5, str: 30, agi: 20, int: 15, stamina: 50 } },
  { id: 121, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "11 + 6", desc: "", stats: { agi: 16, speed: "7,5", moveSpeed: 20 } },
  { id: 122, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "8 + 12", desc: "10% к урону от маны", stats: { int: 16, mpRegen: 5, magicVamp: 10 } },
  { id: 123, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "7 + 13", desc: "", stats: { str: 16, hpRegen: 5, magicResist: 16, physVamp: 10 } },
  { id: 124, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "123 + 122", desc: "12% к урону от маны", stats: { str: 16, int: 16, hpRegen: 5, mpRegen: 5, magicResist: 16, physVamp: 10, magicVamp: 10 } },
  { id: 125, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "122 + 121", desc: "12% к урону от маны", stats: { agi: 16, int: 16, speed: 10, mpRegen: 5, moveSpeed: 20, magicVamp: 10 } },
  { id: 126, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "122 + 123", desc: "", stats: { str: 16, agi: 16, speed: 10, hpRegen: 5, moveSpeed: 20, magicResist: 16, physVamp: 10 } },
  { id: 127, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "121 + 122 + 123", desc: "20% к урону от маны", stats: { str: 30, agi: 30, int: 30, speed: 15, hpRegen: 10, mpRegen: 15, moveSpeed: 40, magicResist: 20, physVamp: 15, magicVamp: 15 } },
  { id: 128, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "122 + 9", desc: "10% к урону от маны. При успешном окончании прочтения вызывает метеор, поражающий врагов в радиусе 400 и оглушающий их на 6 секунд. Оставляет след который наносит 7% периодического магического урона раз в секунду в течение 50 секунд. Вступившие враги горят в течении 3 секунд", stats: { cooldown: 35, str: 6, agi: 6, int: 24, mpRegen: "7,5", magicVamp: 15 } },
  { id: 129, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "123 + 47", desc: "+20% стоимости уклонения. Лишает существо сил, отчего оно не может атаковать в течении 5 секунд", stats: { cooldown: 18, str: 20, hpRegen: 7, magicResist: 16, physVamp: 25 } },
  { id: 130, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "121 + 10", desc: "Создаёт 2 иллюзии вашего героя, которые существуют 8 сек и повторяют все ваши действия", stats: { cooldown: 30, str: 10, agi: 26, int: 10, speed: "7,5", moveSpeed: 20 } },
  { id: 131, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "23 + 20 + 19", desc: "На время действия увеличивает мастерство на 3,5%, силу и здоровье на 25%, но отнимает 3% здоровья в секунду. Вы не можете умереть ни от потери здоровья во время действия способности, ни от спада бонуса к силе после её отключения.", stats: { cooldown: "0,1", armor: 6, speed: "12,5", mastery: "1,5", hpRegen: 5 } },
  { id: 132, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "27 + 7", desc: "Каждая атака может с вероятностью 15% оглушить цель на 0,5 сек. и нанести 90% физического урона", stats: { cooldown: 2, str: 20, mastery: "2,5" } },
  { id: 133, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "132 + 107", desc: "Каждая атака может с вероятностью 25% оглушить цель на 0,5 сек. и нанести 120% физического урона. С вероятностью 60% блокирует 20% урона от атак противника", stats: { cooldown: 1, str: 44, mastery: "3,3", hpRegen: 10, stamina: 35 } },
  { id: 134, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "37 + 24 + 25", desc: "Делает героя невидимым на 14 сек. или до момента, когда он совершит атаку или применит способность. Также увеличивает скорость передвижения на 20% и позволяет проходить сквозь существ. Атака, прерывающая невидимость, дополнительно нанесёт 175% физического урона.", stats: { cooldown: 25, speed: "17,5", mastery: 2 } },
  { id: 135, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "134 + 51", desc: "Делает героя невидимым на 14 сек. или до момента, когда он совершит атаку или применит способность. Эффект также увеличивает скорость передвижения на 25% и позволяет проходить сквозь существ. Атака, прерывающая невидимость, дополнительно нанесёт 300% физического урона", stats: { cooldown: 20, speed: 20, mastery: 6 } },
  { id: 136, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "27 + 27 + 18", desc: "Атаки и заклинания уменьшают все сопротивления цели на 60%. Эффект длится 7 сек.", stats: { mastery: 5 } },
  { id: 137, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "35 + 67", desc: "Атакуемые враги получают 25% магического урона в секунду и наносит на 40% меньше урона заклинаниями. Действует 3 сек", stats: { int: 10, speed: "22,5", mpRegen: 2, magicResist: 20 } },
  { id: 138, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "136 + 137", desc: "Атаки и заклинания уменьшают все сопротивления цели на 90%. Атакуемые враги получают 35% магического и физического урона в секунду и наносит на 40% меньше урона заклинаниями. Эффект длится 7 сек.", stats: { int: 12, speed: "22,5", mastery: 7 } },
  { id: 139, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "14 + 25 + 26 + 45", desc: "Ваши атаки срубает дерево перед вами. Ваши атаки прорубают жертву, нанося врагам в радиусе 650 вокруг неё 30% вашего физического урона", stats: { cooldown: 4, mastery: 6, hpRegen: "7,5", mpRegen: "2,75", stamina: 10 } },
  { id: 140, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "56 + 23", desc: "Развеивает положительные эффекты с цели в момент применения и следующие 5 сек.", stats: { cooldown: 10, armor: 10, mastery: "7,5", hpRegen: 6 } },
  { id: 141, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "51 + 22 + 24", desc: "Каждая атака может с вероятностью в 80% нанести 70% дополнительного магического и физического урона.", stats: { speed: 25, mastery: 4 } },
  { id: 142, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "47 + 56", desc: "+20% стоимости уклонения. Каждую секунду наносит противникам 60% магического урона и ослабляет их, увеличивая время востановления уклонения на 15%. На ваших иллюзиях наносит 35% магического урона в секунду.", stats: { mastery: 6, moveSpeed: 20 } },
  { id: 143, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "56 + 34", desc: "Активация позволяет атаковать бесплотных существ, а каждая атака расходует 10 маны и увеличивается на ту же велечену в течении 6 секнуд.", stats: { cooldown: 9, mastery: 7, physVamp: 20, magicVamp: 20 } },
  { id: 144, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "106 + 51", desc: "Каждый крит может с вероятностью в 40% увеличить ваш крит урон на 225% на следующие 6 секнуд", stats: { mastery: 9, crit: 40, critDmg: 40 } },
  { id: 145, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "94 + 38", desc: "250+ к дальности применения заклинаний и предметов. Активируя придаёт цели бесплотный облик, который полностью защищает от физического урона, но не позволяет атаковать и увеличивает получаемый урон на 40% на 4 сек. Если целью выбран противник, он также замедляется на 80% и получит 50% магического урона", stats: { cooldown: 22, str: 8, agi: 8, int: 8, manaPool: 40 } },
  { id: 146, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "53 + 25 + 47", desc: "+35% стоимости уклонения", stats: { agi: 55, speed: 15, mastery: "2,5" } },
  { id: 147, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "11 + 7", desc: "Каждая ваша атака сжигает 1 ману врага и наносит ему 2% физического урона за единицу сожжённой маны.", stats: { str: 10, agi: 15 } },
  { id: 148, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "147 + 66 + 53", desc: "Раз в 7 секунд развеивает с владельца предмета один негативный эффект ускоряя скорость передвижения на 30 за развеянный эффект, длительность 3 секунды. Каждая ваша атака сжигает 2 маны врага и наносит ему 5% физического урона за единицу сожжённой маны.", stats: { str: 10, agi: 40, armor: 4, mastery: "1,2", moveSpeed: 50 } },
  { id: 149, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "98 + 18 + 50 + 55", desc: "Создаёт область радиусом 200, в которой противники не могут использовать способности 5 сек. По окончании наносит им урон в размере 60% от полученного за время действия эффекта предмета. Каждая атака может с вероятностью в 30% может нанести 70% магического и физического урона.", stats: { cooldown: 25, str: 24, agi: 12, int: 24, speed: 40, mastery: 2, hpRegen: 6, mpRegen: "3,5" } },
  { id: 150, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "46 + 10", desc: "Активация позволяет увеличить урон вашего следующего заклинания на 15%", stats: { cooldown: 6, str: 7, agi: 7, int: 7, manaPool: 20, stamina: 20 } },
  { id: 151, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "150 + 106", desc: "Активация позволяет увеличить урон вашего следующего заклинания на 30%", stats: { cooldown: 6, str: 12, agi: 12, int: 12, mastery: 3, manaPool: 25, stamina: 25, crit: 30, critDmg: 30 } },
  { id: 152, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "55 + 86 + 62", desc: "Отравляет цель на 6 сек., нанося 70% физического и магического урона в секунду и замедляя её передвижение на 70% снижая исцеления на 40%", stats: { str: 26, agi: 26, int: 26, manaPool: 40, stamina: 40 } },
  { id: 153, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "13 + 29 + 25", desc: "Раз в 5 секунд позволяет совершить двойную атаку, вторая атака совершается через 0,6 сек после первой", stats: { str: 15, mastery: 2, mpRegen: 2 } },
  { id: 154, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "153 + 10", desc: "Раз в 5 секунд позволяет совершить двойную атаку, вторая атака совершается через 0,6 сек после первой. Вместе с второй атакой выпускается крюк, который спустя 1 секунду притягивает вас и противника (или цель/место) друг к другу", stats: { str: 25, agi: 10, int: 10, mastery: "2,5", mpRegen: "2,5" } },
  { id: 155, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "36 + 27 + 44 + 52", desc: "Развеивает с вас все негативные эффекты, дает полное сопротивление физическому урону и увеличивая весь вампиризм и силу с этого предмета в 3 раза в течении 6 секунд", stats: { cooldown: 35, str: 30, mastery: 4, physVamp: 40, stamina: 60 } },
  { id: 156, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "102 + 50", desc: "Пассивный эффект: Каждая атака с 40% шансом создаёт создаёт цепную молнию, которая 12 раз перескакивает между врагами в радиусе 650, нанося им 70% магического урона. Активный эффект: Накладывает на всех союзников в радиусе 1200 щит молний, который пускает цепную молнию в случайного врага и наносит им урон, равный 40% их магического и физического урона. Длительность: 12 сек", stats: { cooldown: 45, speed: 40, mastery: "2,5" } },
  { id: 157, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "40 + 52", desc: "Мгновенно перемещает к выбраной точке в радиусе 1200. Перемещение восполняет 20% здоровья. После перемещения наносит урон, равный 63% от физического урона владельца, всем врагам в радиусе 100 и замедляет их передвижение на 150%, а скорость — на 50%. Замедление действует 5 сек.", stats: { cooldown: 6, str: 25 } },
  { id: 158, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "40 + 53", desc: "Мгновенно перемещает к выбраной точке в радиусе 1200. После перемещения владелец на 4 сек. получает +40 к скорости передвижения, +40% к скорости, +4,5% к мастерству", stats: { cooldown: 6, agi: 25 } },
  { id: 159, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "40 + 54", desc: "Мгновенно перемещает к выбраной точке в радиусе 1200. Перемещение восполняет 60 маны", stats: { cooldown: 3, int: 25 } },
  { id: 160, name: "Сборный артефакт", type: "Сборный артефакт", recipe: "83 + 46", desc: "Призывает тотем, который уменьшает весь урон врагов в радиусе 900 на 30% и наносит им 30% физического урона в секунду. Тотем передвигаться за вами и существует 25 сек. Пассивный эффект: Увеличивает вампиризм союзников на 30%, их урон на 6,8%, броню на 6%, восстановление маны на 4. Радиус: 1200", stats: { cooldown: 60, armor: 7, mpRegen: 3, physVamp: 20, manaPool: 20, stamina: 20 } }
